import React, { useState, useEffect } from 'react';
import { apiClient } from '../../shared/services/api';
import { useNotification } from '../../shared/context/NotificationContext';
import { VirtualMeetingModal } from './VirtualMeetingModal';
import { Calendar, Video, Clock, CheckCircle2, ExternalLink } from 'lucide-react';

export const SessionTracker = ({ mentorshipId, isMentor }) => {
  const { showNotification } = useNotification();
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeVirtualSession, setActiveVirtualSession] = useState(null);
  const [completingSessionId, setCompletingSessionId] = useState(null);

  const fetchSessions = async () => {
    try {
      const res = await apiClient(`/sessions/sessions/mentorship/${mentorshipId}`);
      setSessions(res.data || []);
    } catch (err) {
      console.error('Failed to load sessions:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (mentorshipId) fetchSessions();
  }, [mentorshipId]);

  const handleConfirmSlot = async (sessionId, selectedSlot) => {
    try {
      await apiClient(`/sessions/sessions/${sessionId}/notes`, {
        method: 'PATCH',
        body: JSON.stringify({
          selectedSlot,
          status: 'CONFIRMED'
        })
      });
      showNotification('Session time confirmed and finalized!', 'success');
      fetchSessions();
    } catch (err) {
      showNotification(err.message, 'error');
    }
  };

  const handleCompleteSession = async (sessionId) => {
    setCompletingSessionId(sessionId);
    try {
      await apiClient(`/sessions/sessions/${sessionId}/complete`, { method: 'PATCH' });
      showNotification('Session marked as completed. Your mentor has been notified.', 'success');
      await fetchSessions();
    } catch (err) {
      showNotification(err.message, 'error');
    } finally {
      setCompletingSessionId(null);
    }
  };

  if (loading) return <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>Loading 1-on-1 sessions...</p>;

  return (
    <div style={{ marginTop: '1rem', background: 'var(--bg-subtle)', padding: '1rem', borderRadius: '10px', border: '1px solid var(--border-card)' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem', flexWrap: 'wrap', gap: '0.5rem' }}>
        <h5 style={{ fontSize: '0.95rem', color: 'var(--text-main)', margin: 0, display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Calendar size={16} color="var(--primary)" /> 1-on-1 Virtual Sessions ({sessions.length})
        </h5>

        <button
          onClick={() => setActiveVirtualSession({
            id: `inst-${mentorshipId}`,
            topic: '1-on-1 Instant Mentorship & Code Session',
            mentorship_id: mentorshipId
          })}
          className="btn btn-primary btn-sm"
          style={{ fontSize: '0.78rem', background: 'linear-gradient(135deg, #0284c7 0%, #2563eb 100%)' }}
        >
          <Video size={14} /> Launch Instant 1-on-1 Video Call
        </button>
      </div>

      {sessions.length === 0 ? (
        <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', margin: 0 }}>
          No scheduled session times found. Click <strong>Launch Instant 1-on-1 Video Call</strong> above to start a live WebRTC audio/video call, collaborative whiteboard & code sandbox!
        </p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
        {sessions.map(s => {
          const isPendingSelection = s.status === 'PENDING_SLOT_SELECTION';
          const isCompleted = s.status === 'COMPLETED';
          const canStudentComplete = !isMentor && ['CONFIRMED', 'SCHEDULED'].includes(s.status);
          const proposedSlots = s.proposed_slots || [s.scheduled_at];

          return (
            <div key={s.id} style={{ background: 'var(--bg-card)', padding: '0.85rem', borderRadius: '8px', border: '1px solid var(--border-card)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.5rem' }}>
                <div>
                  <p style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--text-main)' }}>{s.topic}</p>
                  <p style={{ fontSize: '0.78rem', color: 'var(--text-muted)' }}>Duration: {s.duration_mins} Minutes</p>
                </div>
                <span className={`badge ${isPendingSelection ? 'badge-amber' : isCompleted ? 'badge-emerald' : 'badge-cyan'}`}>
                  {isPendingSelection ? 'Slot Selection Pending' : isCompleted ? 'Completed' : s.status === 'SCHEDULED' ? 'Scheduled' : 'Confirmed'}
                </span>
              </div>

              {/* Proposed Slots Selection View */}
              {isPendingSelection ? (
                <div style={{ background: 'var(--bg-subtle)', border: '1px solid var(--border-card)', padding: '0.75rem', borderRadius: '6px', marginTop: '0.5rem' }}>
                  <p style={{ fontSize: '0.78rem', fontWeight: 700, color: 'var(--accent-amber)', marginBottom: '0.4rem' }}>
                    {isMentor ? '👉 Student Proposed 3 Convenient Time Slots. Select 1 to Finalize:' : '⏳ Waiting for Mentor to pick 1 of your proposed slots:'}
                  </p>

                  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem' }}>
                    {proposedSlots.map((slotTime, idx) => (
                      <div key={idx} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'var(--bg-card)', padding: '0.4rem 0.6rem', borderRadius: '4px', border: '1px solid var(--border-card)' }}>
                        <span style={{ fontSize: '0.8rem', color: 'var(--text-main)', fontWeight: 600 }}>
                          Option {idx + 1}: {new Date(slotTime).toLocaleString()}
                        </span>

                        {isMentor && (
                          <button
                            onClick={() => handleConfirmSlot(s.id, slotTime)}
                            className="btn btn-primary btn-sm"
                            style={{ fontSize: '0.725rem', padding: '0.2rem 0.5rem' }}
                          >
                            <CheckCircle2 size={12} /> Finalize Slot {idx + 1}
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              ) : (
                /* Confirmed Session Final Time & Native Embedded Video Meeting Button */
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '0.6rem', marginTop: '0.5rem', paddingTop: '0.5rem', borderTop: '1px solid var(--border-card)' }}>
                  <div>
                    <p style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--accent-emerald)', display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                      <Clock size={14} /> Finalized Time: {new Date(s.scheduled_at).toLocaleString()}
                    </p>
                  </div>

                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap' }}>
                    {canStudentComplete && (
                      <button
                        onClick={() => handleCompleteSession(s.id)}
                        className="btn btn-secondary btn-sm"
                        disabled={completingSessionId === s.id}
                        style={{ fontSize: '0.75rem', color: 'var(--accent-emerald)', borderColor: 'var(--accent-emerald)' }}
                      >
                        <CheckCircle2 size={14} /> {completingSessionId === s.id ? 'Saving…' : 'Mark completed'}
                      </button>
                    )}
                    {!isCompleted && (
                      <button
                        onClick={() => setActiveVirtualSession(s)}
                        className="btn btn-primary btn-sm"
                        style={{ fontSize: '0.75rem' }}
                      >
                        <Video size={14} /> Launch In-App Video Call
                      </button>
                    )}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
      )}

      {/* Embedded 1-on-1 Virtual Video Conference Modal */}
      {activeVirtualSession && (
        <VirtualMeetingModal
          session={activeVirtualSession}
          isOpen={Boolean(activeVirtualSession)}
          onClose={() => setActiveVirtualSession(null)}
        />
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import {
  X,
  Video,
  VideoOff,
  Mic,
  MicOff,
  Share2,
  Copy,
  Maximize2,
  ShieldCheck,
  Code,
  PenTool,
  MessageSquare,
  Play,
  RotateCcw,
  Sparkles,
  Users,
  Check
} from 'lucide-react';
import { useAuth } from '../../shared/context/AuthContext';
import { useNotification } from '../../shared/context/NotificationContext';

export const VirtualMeetingModal = ({ session, isOpen, onClose }) => {
  const { user } = useAuth();
  const { showNotification } = useNotification();
  const [activeTab, setActiveTab] = useState('video'); // 'video' | 'whiteboard' | 'code' | 'chat'

  // WebRTC Native HTML5 Media Stream States
  const [cameraActive, setCameraActive] = useState(true);
  const [micActive, setMicActive] = useState(true);
  const [screenSharing, setScreenSharing] = useState(false);
  const [copied, setCopied] = useState(false);

  const localVideoRef = useRef(null);
  const mediaStreamRef = useRef(null);

  // In-Call Live Chat State
  const [messages, setMessages] = useState([
    { sender: 'System', text: '🔒 1-on-1 Encrypted Virtual Session Started.', time: 'Now' },
    { sender: session?.mentor_name || 'Alumni Mentor', text: `Welcome to our mentorship call! Let's discuss ${session?.topic || 'career guidance'}.`, time: 'Now' }
  ]);
  const [chatInput, setChatInput] = useState('');

  // Interactive Code Sandbox State
  const [codeSnippet, setCodeSnippet] = useState(
    `// 1-on-1 Technical Interview & Live Coding Sandbox\n// Topic: ${session?.topic || 'Data Structures & System Architecture'}\n\nfunction solveSystemProblem(inputData) {\n  console.log("Analyzing input:", inputData);\n  const result = inputData.map(x => x * 2);\n  return result;\n}\n\n// Run code below:\nconsole.log("Output:", solveSystemProblem([10, 20, 30, 40]));`
  );
  const [codeConsoleOutput, setCodeConsoleOutput] = useState('');

  // Collaborative Whiteboard Canvas Refs & State
  const canvasRef = useRef(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [drawColor, setDrawColor] = useState('#0284c7');

  // Start Native HTML5 WebRTC Camera & Mic Stream on Mount
  useEffect(() => {
    if (!isOpen) return;

    let isMounted = true;
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: true,
          audio: true
        });
        if (isMounted) {
          mediaStreamRef.current = stream;
          if (localVideoRef.current) {
            localVideoRef.current.srcObject = stream;
          }
        }
      } catch (err) {
        console.warn('Camera/Mic permission not granted or device unavailable:', err.message);
      }
    };

    startCamera();

    return () => {
      isMounted = false;
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
    };
  }, [isOpen]);

  // Toggle Camera Track
  const toggleCamera = () => {
    if (mediaStreamRef.current) {
      const videoTrack = mediaStreamRef.current.getVideoTracks()[0];
      if (videoTrack) {
        videoTrack.enabled = !cameraActive;
      }
    }
    setCameraActive(!cameraActive);
  };

  // Toggle Mic Track
  const toggleMic = () => {
    if (mediaStreamRef.current) {
      const audioTrack = mediaStreamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !micActive;
      }
    }
    setMicActive(!micActive);
  };

  // Toggle Native HTML5 Screen Sharing
  const toggleScreenShare = async () => {
    if (!screenSharing) {
      try {
        const screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        if (localVideoRef.current) {
          localVideoRef.current.srcObject = screenStream;
        }
        setScreenSharing(true);
        screenStream.getVideoTracks()[0].onended = () => {
          setScreenSharing(false);
          if (localVideoRef.current && mediaStreamRef.current) {
            localVideoRef.current.srcObject = mediaStreamRef.current;
          }
        };
      } catch (err) {
        showNotification('Screen sharing cancelled', 'info');
      }
    } else {
      setScreenSharing(false);
      if (localVideoRef.current && mediaStreamRef.current) {
        localVideoRef.current.srcObject = mediaStreamRef.current;
      }
    }
  };

  // Handle Code Execution in Sandbox
  const handleRunCode = () => {
    try {
      const logs = [];
      const customConsole = {
        log: (...args) => logs.push(args.map(a => typeof a === 'object' ? JSON.stringify(a) : String(a)).join(' ')),
        error: (...args) => logs.push('[ERROR] ' + args.join(' '))
      };

      const runFn = new Function('console', codeSnippet);
      runFn(customConsole);
      setCodeConsoleOutput(logs.join('\n') || 'Code executed successfully with zero output errors!');
      showNotification('Code executed cleanly!', 'success');
    } catch (err) {
      setCodeConsoleOutput(`Runtime Error: ${err.message}`);
      showNotification('Syntax error in code execution', 'error');
    }
  };

  // Send In-Call Live Chat Message
  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!chatInput.trim()) return;

    setMessages(prev => [
      ...prev,
      { sender: 'You', text: chatInput, time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }
    ]);
    setChatInput('');
  };

  // Whiteboard Canvas Drawing Logic
  const startDrawing = (e) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    ctx.beginPath();
    ctx.moveTo(e.clientX - rect.left, e.clientY - rect.top);
    ctx.strokeStyle = drawColor;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    setIsDrawing(true);
  };

  const draw = (e) => {
    if (!isDrawing) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
    ctx.stroke();
  };

  const stopDrawing = () => {
    setIsDrawing(false);
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  };

  if (!isOpen || !session) return null;

  return (
    <div
      className="modal-overlay"
      onClick={onClose}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        width: '100vw',
        height: '100vh',
        background: 'rgba(5, 8, 15, 0.95)',
        backdropFilter: 'blur(12px)',
        zIndex: 99999,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '0.5rem',
        overflowY: 'auto',
        boxSizing: 'border-box'
      }}
    >
      <div
        className="modal-content"
        onClick={(e) => e.stopPropagation()}
        style={{
          width: '98vw',
          maxWidth: '1350px',
          height: '92vh',
          maxHeight: 'calc(100dvh - 1rem)',
          background: '#0a0f1d',
          border: '1px solid #1e293b',
          borderRadius: '16px',
          display: 'flex',
          flexDirection: 'column',
          overflowY: 'auto',
          overflowX: 'hidden',
          padding: 0,
          boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.8)'
        }}
      >
        {/* Top Meeting Header Bar */}
        <div
          style={{
            minHeight: '60px',
            height: 'auto',
            background: '#111827',
