import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { apiClient } from '../services/api';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(() => {
    try {
      const savedUser = localStorage.getItem('campusbridge_user');
      return savedUser ? JSON.parse(savedUser) : null;
    } catch (e) {
      return null;
    }
  });
  const [token, setToken] = useState(() => localStorage.getItem('campusbridge_token') || null);
  const [loading, setLoading] = useState(false);
  const heartbeatRef = useRef(null);

  // Send presence heartbeat every 30s while logged in
  useEffect(() => {
    if (!token) {
      clearInterval(heartbeatRef.current);
      return;
    }
    const beat = () => apiClient('/presence/heartbeat', { method: 'POST' }).catch(() => {});
    beat();
    heartbeatRef.current = setInterval(beat, 30000);
    const onVisible = () => { if (!document.hidden) beat(); };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      clearInterval(heartbeatRef.current);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [token]);

  const fetchCurrentUser = async () => {
    if (!token) {
      setUser(null);
      localStorage.removeItem('campusbridge_user');
      return;
    }
    try {
      const res = await apiClient('/auth/me');
      if (res.data) {
        setUser(res.data);
        localStorage.setItem('campusbridge_user', JSON.stringify(res.data));
      }
    } catch (err) {
      console.warn('Auth validation failed:', err.message);
      logout();
    }
  };

  useEffect(() => {
    if (token) {
      fetchCurrentUser();
    }
  }, [token]);

  const loginUser = async (email, password) => {
    const res = await apiClient('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password })
    });
    const { user: userData, token: jwtToken } = res.data;
    localStorage.setItem('campusbridge_token', jwtToken);
    localStorage.setItem('campusbridge_user', JSON.stringify(userData));
    setToken(jwtToken);
    setUser(userData);
    return userData;
  };

  const registerStudentUser = async (formData) => {
    const res = await apiClient('/auth/register/student', {
      method: 'POST',
      body: formData
    });
    const { user: userData, token: jwtToken } = res.data;
    localStorage.setItem('campusbridge_token', jwtToken);
    localStorage.setItem('campusbridge_user', JSON.stringify(userData));
    setToken(jwtToken);
    setUser(userData);
    return userData;
  };

  const registerAlumniUser = async (formData) => {
    const res = await apiClient('/auth/register/alumni', {
      method: 'POST',
      body: formData
    });
    const { user: userData, token: jwtToken } = res.data;
    localStorage.setItem('campusbridge_token', jwtToken);
    localStorage.setItem('campusbridge_user', JSON.stringify(userData));
    setToken(jwtToken);
    setUser(userData);
    return userData;
  };

  const logout = () => {
    localStorage.removeItem('campusbridge_token');
    localStorage.removeItem('campusbridge_user');
    setToken(null);
    setUser(null);
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        loading,
        login: loginUser,
        registerStudent: registerStudentUser,
        registerAlumni: registerAlumniUser,
        logout,
        refreshUser: fetchCurrentUser
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);

import React, { createContext, useContext, useState } from 'react';

const NotificationContext = createContext(null);

export const NotificationProvider = ({ children }) => {
  const [notification, setNotification] = useState(null);

  const showNotification = (message, type = 'info') => {
    setNotification({ message, type });
    setTimeout(() => {
      setNotification(null);
    }, 4000);
  };

  return (
    <NotificationContext.Provider value={{ showNotification }}>
      {children}
      {notification && (
        <div
          style={{
            position: 'fixed',
            bottom: '24px',
            right: '24px',
            zIndex: 9999,
            padding: '12px 20px',
            borderRadius: '12px',
            background:
              notification.type === 'error'
                ? 'rgba(244, 63, 94, 0.95)'
                : notification.type === 'success'
                ? 'rgba(16, 185, 129, 0.95)'
                : 'rgba(6, 182, 212, 0.95)',
            color: '#ffffff',
            boxShadow: '0 10px 25px rgba(0,0,0,0.4)',
            fontWeight: 600,
            fontSize: '0.9rem',
            backdropFilter: 'blur(10px)',
            animation: 'fadeIn 0.3s ease'
          }}
        >
          {notification.message}
        </div>
      )}
    </NotificationContext.Provider>
  );
};

export const useNotification = () => useContext(NotificationContext);

const DEFAULT_HOST = typeof window !== 'undefined' && window.location.hostname ? window.location.hostname : 'localhost';
const ENV_API_URL = import.meta.env?.VITE_API_BASE_URL;

const IS_HTTPS = typeof window !== 'undefined' && window.location.protocol === 'https:';
const RENDER_PROD_API_URL = 'https://alumni-platform-pv27.onrender.com/api/v1';

const PORTS_TO_PROBE = [5000, 5001, 5002, 5003, 5004, 5005, 5006, 5007, 5008, 5010, 5012, 5015, 5020];

let cachedActiveApiBaseUrl = (() => {
  if (ENV_API_URL && (IS_HTTPS ? ENV_API_URL.startsWith('https://') : true)) {
    return ENV_API_URL;
  }
  if (IS_HTTPS) {
    return RENDER_PROD_API_URL;
  }
  return null;
})();

let activePortPromise = null;
let sessionValidation = null;

const isCurrentSessionInvalid = async (token) => {
  if (!token) return true;
  if (!sessionValidation || sessionValidation.token !== token) {
    const promise = fetch(`${getApiOrigin()}/api/v1/auth/me`, {
      headers: { Authorization: `Bearer ${token}` },
      cache: 'no-store'
    })
      .then((response) => response.status === 401)
      .catch(() => false);
    sessionValidation = {
      token,
      promise
    };
    promise.then(() => {
      if (sessionValidation?.promise === promise) sessionValidation = null;
    });
  }
  return await sessionValidation.promise;
};

export const getActiveApiUrl = async (forceRefresh = false) => {
  if (!forceRefresh && cachedActiveApiBaseUrl && typeof cachedActiveApiBaseUrl === 'string') {
    return cachedActiveApiBaseUrl;
  }

  if (IS_HTTPS) {
    cachedActiveApiBaseUrl = (ENV_API_URL && ENV_API_URL.startsWith('https://')) ? ENV_API_URL : RENDER_PROD_API_URL;
    return cachedActiveApiBaseUrl;
  }

  if (!forceRefresh) {
    const saved = typeof localStorage !== 'undefined' ? localStorage.getItem('campusbridge_active_api_url') : null;
    if (saved && !saved.startsWith('http://')) {
      try {
        const res = await fetch(`${saved}/health`, { signal: AbortSignal.timeout(300) });
        if (res.ok) {
          const data = await res.json();
          if (data.service?.includes('CampusBridge')) {
            cachedActiveApiBaseUrl = saved;
            return saved;
          }
        }
      } catch (e) {
        // Saved port offline or stale
      }
    }
  }

  activePortPromise = (async () => {
    for (const port of PORTS_TO_PROBE) {
      const url = `http://${DEFAULT_HOST}:${port}/api/v1`;
      try {
        const res = await fetch(`${url}/health`, { signal: AbortSignal.timeout(250) });
        if (res.ok) {
          const data = await res.json();
          if (data.service?.includes('CampusBridge')) {
            cachedActiveApiBaseUrl = url;
            if (typeof localStorage !== 'undefined') {
              localStorage.setItem('campusbridge_active_api_url', url);
            }
            return url;
          }
        }
      } catch (e) {
        // Continue to next port
      }
    }

    const fallbackUrl = `http://${DEFAULT_HOST}:5001/api/v1`;
    cachedActiveApiBaseUrl = fallbackUrl;
    return fallbackUrl;
  })();

  return await activePortPromise;
};

export const getApiOrigin = () => {
  const base = cachedActiveApiBaseUrl || (IS_HTTPS ? RENDER_PROD_API_URL : `http://${DEFAULT_HOST}:5001/api/v1`);
  return base.replace(/\/api\/v1\/?$/, '');
};

export const getAssetUrl = (pathStr) => {
  if (!pathStr) return '';
  if (pathStr.startsWith('http://') || pathStr.startsWith('https://') || pathStr.startsWith('data:')) {
    return pathStr;
  }
  // Support legacy database rows that contain a Cloudinary public ID instead
  // of the full secure_url. New uploads persist the secure_url directly.
  const cloudinaryPublicId = pathStr.replace(/^\/+/, '');
  if (/^campusbridge\/(alumni_ids|student_ids|job_descriptions|milestone_materials|resumes|study_resources|announcements)\//i.test(cloudinaryPublicId)) {
    const cloudName = import.meta.env.VITE_CLOUDINARY_CLOUD_NAME || 'dfutwx64f';
    return `https://res.cloudinary.com/${cloudName}/image/upload/${cloudinaryPublicId}`;
  }
  const origin = getApiOrigin();
  const cleanPath = pathStr.startsWith('/') ? pathStr : `/${pathStr}`;
  return `${origin}${cleanPath}`;
};

export const apiClient = async (endpoint, options = {}) => {
  let baseUrl = await getActiveApiUrl();
  const token = typeof localStorage !== 'undefined' ? localStorage.getItem('campusbridge_token') : null;

  const isFormData = typeof FormData !== 'undefined' && options.body instanceof FormData;
  const headers = {
    ...(isFormData ? {} : { 'Content-Type': 'application/json' }),
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
    ...options.headers
  };
  if (isFormData) {
    delete headers['Content-Type'];
  }

  // Normalize endpoint to always include /api/v1 prefix cleanly
  let rawEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
  if (rawEndpoint.startsWith('/api/v1')) {
    rawEndpoint = rawEndpoint.replace('/api/v1', '');
  }

  const rootOrigin = getApiOrigin();
  const fullUrl = `${rootOrigin}/api/v1${rawEndpoint}`;

  let response;
  try {
    response = await fetch(fullUrl, {
      ...options,
      headers
    });
  } catch (netErr) {
    // Port failed/changed: clear cache, force refresh discovery, and retry request
    cachedActiveApiBaseUrl = null;
    if (typeof localStorage !== 'undefined') {
      localStorage.removeItem('campusbridge_active_api_url');
    }
    const freshBaseUrl = await getActiveApiUrl(true);
    const freshOrigin = freshBaseUrl.replace(/\/api\/v1\/?$/, '');
    response = await fetch(`${freshOrigin}/api/v1${rawEndpoint}`, {
      ...options,
      headers
    });
  }

  // If request returned 404 non-JSON, re-verify port and retry once
  if (response.status === 404) {
    const textPreview = await response.clone().text();
    if (textPreview.includes('<!DOCTYPE html>') || textPreview.includes('Cannot POST') || textPreview.includes('Cannot GET')) {
      cachedActiveApiBaseUrl = null;
      if (typeof localStorage !== 'undefined') {
        localStorage.removeItem('campusbridge_active_api_url');
      }
      const freshBaseUrl = await getActiveApiUrl(true);
      const freshOrigin = freshBaseUrl.replace(/\/api\/v1\/?$/, '');
      if (`${freshOrigin}/api/v1` !== baseUrl) {
        response = await fetch(`${freshOrigin}/api/v1${rawEndpoint}`, {
          ...options,
          headers
        });
      }
    }
  }

  const contentType = response.headers.get('content-type');
  if (!contentType || !contentType.includes('application/json')) {
    const rawText = await response.text();
    throw new Error(
      `Server returned non-JSON error (${response.status}) from endpoint '${endpoint}': ${rawText.slice(0, 150)}`
    );
  }

  const data = await response.json();

  if (!response.ok) {
    // A single protected endpoint may reject for a route-specific reason.
    // Validate the token itself before ending the user's session.
    const isAuthEndpoint = rawEndpoint.startsWith('/auth/');
    if (response.status === 401 && !isAuthEndpoint) {
      const tokenIsInvalid = await isCurrentSessionInvalid(token);
      if (tokenIsInvalid) {
        if (typeof localStorage !== 'undefined') {
          localStorage.removeItem('campusbridge_token');
          localStorage.removeItem('campusbridge_user');
          localStorage.removeItem('campusbridge_active_tab');
        }
        if (typeof window !== 'undefined') {
          window.dispatchEvent(new CustomEvent('campusbridge:session_expired'));
        }
      }
    }
    throw new Error(data.message || 'An error occurred while communicating with the server');
  }

  // Automatically refresh notifications across UI after state mutations
  if (options.method && options.method.toUpperCase() !== 'GET' && !rawEndpoint.includes('/notifications')) {
    if (typeof window !== 'undefined') {
      setTimeout(() => {
        window.dispatchEvent(new CustomEvent('campusbridge:notification_refresh'));
      }, 150);
    }
  }

  return data;
};
